-- ============================================================================
-- Source: 023_create_raw_claims_table.sql
-- ============================================================================

-- Migration 023: Create staging.raw_claims table for two-stage processing pipeline
-- Purpose: Decouple file ingestion from claim validation
-- Stage 1: Files -> raw_claims (fast ingestion)
-- Stage 2: raw_claims -> encounters/errors (validated processing)

-- Create raw_claims table for storing parsed but unvalidated claims
CREATE TABLE IF NOT EXISTS staging.raw_claims (
    raw_claim_id BIGINT GENERATED ALWAYS AS IDENTITY (CACHE 100) PRIMARY KEY,
    batch_id BIGINT NOT NULL REFERENCES staging.import_batch(batch_id) ON DELETE CASCADE,
    queue_id BIGINT NOT NULL REFERENCES staging.file_processing_queue(queue_id) ON DELETE CASCADE,

    -- Original parsed data stored as JSONB for flexibility
    -- Allows storing any claim format without schema changes
    encounter_fields JSONB NOT NULL,
    service_line_fields JSONB,
    diagnosis_fields JSONB,

    -- Metadata from original file
    row_number INTEGER NOT NULL,
    facility_code TEXT,

    -- Processing status tracking
    processing_status TEXT NOT NULL DEFAULT 'PENDING',
    -- PENDING: Not yet processed by Stage 2
    -- PROCESSING: Currently being processed by Stage 2
    -- COMPLETED: Successfully inserted to claims.encounter
    -- FAILED: Validation failed, logged to staging.import_error_log

    -- Timestamps for tracking pipeline latency
    ingested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMPTZ,

    -- Error tracking (populated if processing_status = FAILED)
    error_message TEXT,

    -- FIFO ordering field (extracted from encounter_fields for performance)
    date_of_service_from DATE,

    -- Ensure valid status values
    CONSTRAINT ck_raw_claims_status CHECK (
        processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED')
    )
);

-- Primary index for Stage 2 processor to find next batch of pending claims
-- Partial index only on PENDING/PROCESSING for efficiency
CREATE INDEX IF NOT EXISTS idx_raw_claims_pending ON staging.raw_claims(ingested_at ASC)
    WHERE processing_status IN ('PENDING', 'PROCESSING');

-- Index for tracking claims by batch (useful for batch status queries)
CREATE INDEX IF NOT EXISTS idx_raw_claims_batch ON staging.raw_claims(batch_id, processing_status);

-- Index for tracking claims by queue (useful for queue metrics)
CREATE INDEX IF NOT EXISTS idx_raw_claims_queue ON staging.raw_claims(queue_id, processing_status);

-- Index for FIFO compliance within facilities (if needed for prioritization)
CREATE INDEX IF NOT EXISTS idx_raw_claims_fifo ON staging.raw_claims(facility_code, date_of_service_from ASC, ingested_at ASC)
    WHERE processing_status = 'PENDING';

-- Index for finding stale PROCESSING claims (for recovery after crashes)
CREATE INDEX IF NOT EXISTS idx_raw_claims_stale ON staging.raw_claims(processing_status, ingested_at)
    WHERE processing_status = 'PROCESSING';

-- Add comment explaining table purpose
COMMENT ON TABLE staging.raw_claims IS 'Two-stage processing pipeline: Stage 1 stores raw parsed claims here before Stage 2 validates and inserts to encounters';
COMMENT ON COLUMN staging.raw_claims.encounter_fields IS 'Patient, subscriber, facility, payer data as JSONB';
COMMENT ON COLUMN staging.raw_claims.service_line_fields IS 'Procedure codes, charges, dates as JSONB array';
COMMENT ON COLUMN staging.raw_claims.diagnosis_fields IS 'ICD diagnosis codes as JSONB array';
COMMENT ON COLUMN staging.raw_claims.processing_status IS 'PENDING (not processed) | PROCESSING (in progress) | COMPLETED (inserted to encounters) | FAILED (validation error)';

-- Update import_batch table to support new INGESTING/INGESTED states for Stage 1
-- Current states: PENDING, PROCESSING, COMPLETED, FAILED
-- New states needed: INGESTING (Stage 1 in progress), INGESTED (Stage 1 done, Stage 2 pending)

-- First, check if we need to update the constraint
DO $$
BEGIN
    -- Drop existing constraint if it exists
    IF EXISTS (
        SELECT 1 FROM information_schema.constraint_column_usage
        WHERE table_schema = 'staging'
        AND table_name = 'import_batch'
        AND constraint_name = 'ck_import_batch_import_status'
    ) THEN
        ALTER TABLE staging.import_batch DROP CONSTRAINT ck_import_batch_import_status;
    END IF;

    -- Add new constraint with additional states
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.constraint_column_usage
        WHERE table_schema = 'staging'
        AND table_name = 'import_batch'
        AND constraint_name = 'ck_import_batch_import_status'
    ) THEN
        ALTER TABLE staging.import_batch ADD CONSTRAINT ck_import_batch_import_status CHECK (
            import_status IN ('PENDING', 'QUEUED', 'INGESTING', 'INGESTED', 'PROCESSING', 'COMPLETED', 'FAILED')
        );
    END IF;
END $$;

-- Note: Can't add comment on constraint in this version, skipping

-- Add new column to processing_metrics to track which stage is being measured
ALTER TABLE staging.processing_metrics ADD COLUMN IF NOT EXISTS processing_stage TEXT DEFAULT 'IMPORT';
-- IMPORT: Legacy single-stage processing
-- INGEST: Stage 1 (file -> raw_claims)
-- PROCESS: Stage 2 (raw_claims -> encounters/errors)

COMMENT ON COLUMN staging.processing_metrics.processing_stage IS 'IMPORT (legacy) | INGEST (Stage 1: file->staging) | PROCESS (Stage 2: staging->encounters)';

-- Create view for monitoring raw_claims processing status
CREATE OR REPLACE VIEW staging.vw_raw_claims_status AS
SELECT
    b.batch_id,
    b.file_path,
    b.import_status,
    COUNT(*) AS total_claims,
    COUNT(*) FILTER (WHERE rc.processing_status = 'PENDING') AS pending_claims,
    COUNT(*) FILTER (WHERE rc.processing_status = 'PROCESSING') AS processing_claims,
    COUNT(*) FILTER (WHERE rc.processing_status = 'COMPLETED') AS completed_claims,
    COUNT(*) FILTER (WHERE rc.processing_status = 'FAILED') AS failed_claims,
    MIN(rc.ingested_at) AS first_ingested_at,
    MAX(rc.processed_at) AS last_processed_at,
    -- Calculate average processing time for completed claims
    AVG(EXTRACT(EPOCH FROM (rc.processed_at - rc.ingested_at))) FILTER (WHERE rc.processing_status = 'COMPLETED') AS avg_processing_seconds
FROM staging.import_batch b
LEFT JOIN staging.raw_claims rc ON b.batch_id = rc.batch_id
GROUP BY b.batch_id, b.file_path, b.import_status;

COMMENT ON VIEW staging.vw_raw_claims_status IS 'Monitoring view: raw_claims processing progress by batch';

-- Create function to mark stale PROCESSING claims back to PENDING (for recovery after crashes)
CREATE OR REPLACE FUNCTION staging.recover_stale_raw_claims(stale_threshold_minutes INTEGER DEFAULT 30)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    recovered_count INTEGER;
BEGIN
    -- Find claims that have been in PROCESSING state for too long
    -- These are likely from crashed workers
    UPDATE staging.raw_claims
    SET processing_status = 'PENDING',
        error_message = 'Recovered from stale PROCESSING state at ' || CURRENT_TIMESTAMP
    WHERE processing_status = 'PROCESSING'
    AND ingested_at < CURRENT_TIMESTAMP - (stale_threshold_minutes || ' minutes')::INTERVAL;

    GET DIAGNOSTICS recovered_count = ROW_COUNT;

    RETURN recovered_count;
END;
$$;

COMMENT ON FUNCTION staging.recover_stale_raw_claims IS 'Recovery function: marks stale PROCESSING claims back to PENDING (default: 30 min threshold)';

-- ============================================================================
-- Source: 024_add_batch_sequence_tracking.sql
-- ============================================================================

-- Migration 024: Add batch sequence tracking for strict FIFO ordering
-- Purpose: Enable Sequential Completion Manager for multi-worker pipeline
-- Architecture: Aegis-inspired sequence-controlled batch processing

-- Add batch_sequence_number to raw_claims for strict FIFO ordering
ALTER TABLE staging.raw_claims
ADD COLUMN IF NOT EXISTS batch_sequence_number INTEGER;

-- Index for sequence-based queries (used by workers to fetch batches)
CREATE INDEX IF NOT EXISTS idx_raw_claims_sequence_status
ON staging.raw_claims(batch_sequence_number, processing_status)
WHERE processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED');

-- Table to track batch sequences (audit trail + coordination)
CREATE TABLE IF NOT EXISTS staging.batch_sequences (
    sequence_number INTEGER PRIMARY KEY,
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMPTZ,

    -- Batch metadata
    batch_id BIGINT NOT NULL REFERENCES staging.import_batch(batch_id) ON DELETE CASCADE,
    claim_count INTEGER NOT NULL,
    processing_stage TEXT NOT NULL DEFAULT 'STAGE2',

    -- Worker tracking
    worker_id TEXT,

    -- Processing metrics
    processing_time_seconds REAL,
    success_count INTEGER DEFAULT 0,
    failure_count INTEGER DEFAULT 0,

    -- Error tracking
    errors JSONB,

    CONSTRAINT ck_batch_sequences_stage CHECK (
        processing_stage IN ('STAGE2', 'VALIDATION', 'RULES', 'COMPLETION')
    )
);

-- Index for finding incomplete sequences (monitoring)
CREATE INDEX IF NOT EXISTS idx_batch_sequences_incomplete
ON staging.batch_sequences(sequence_number)
WHERE completed_at IS NULL;

-- Index for performance analysis
CREATE INDEX IF NOT EXISTS idx_batch_sequences_performance
ON staging.batch_sequences(assigned_at, completed_at, processing_time_seconds);

-- Add comments
COMMENT ON TABLE staging.batch_sequences IS 'Tracks batch sequence numbers for strict FIFO ordering with multi-worker processing';
COMMENT ON COLUMN staging.batch_sequences.sequence_number IS 'Monotonic sequence number assigned by SequencedBatchAcquirer (1, 2, 3...)';
COMMENT ON COLUMN staging.batch_sequences.completed_at IS 'When batch was committed to production (set by SequentialCompletionManager)';
COMMENT ON COLUMN staging.raw_claims.batch_sequence_number IS 'Sequence number for FIFO ordering (assigned at batch acquisition time)';

-- Create view for monitoring sequence processing
CREATE OR REPLACE VIEW staging.vw_sequence_processing_status AS
SELECT
    bs.sequence_number,
    bs.assigned_at,
    bs.completed_at,
    bs.batch_id,
    b.file_path,
    bs.claim_count,
    bs.processing_stage,
    bs.worker_id,
    bs.processing_time_seconds,
    bs.success_count,
    bs.failure_count,

    -- Calculate wait time for incomplete sequences
    CASE
        WHEN bs.completed_at IS NULL THEN
            EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - bs.assigned_at))
        ELSE NULL
    END AS wait_time_seconds,

    -- Identify stuck sequences (waiting > 5 minutes)
    CASE
        WHEN bs.completed_at IS NULL AND bs.assigned_at < CURRENT_TIMESTAMP - INTERVAL '5 minutes' THEN
            TRUE
        ELSE FALSE
    END AS is_stuck,

    -- Count pending claims in this sequence
    (SELECT COUNT(*) FROM staging.raw_claims
     WHERE batch_sequence_number = bs.sequence_number
     AND processing_status = 'PENDING') AS pending_claims,

    -- Count processing claims in this sequence
    (SELECT COUNT(*) FROM staging.raw_claims
     WHERE batch_sequence_number = bs.sequence_number
     AND processing_status = 'PROCESSING') AS processing_claims,

    -- Count completed claims in this sequence
    (SELECT COUNT(*) FROM staging.raw_claims
     WHERE batch_sequence_number = bs.sequence_number
     AND processing_status = 'COMPLETED') AS completed_claims,

    -- Count failed claims in this sequence
    (SELECT COUNT(*) FROM staging.raw_claims
     WHERE batch_sequence_number = bs.sequence_number
     AND processing_status = 'FAILED') AS failed_claims

FROM staging.batch_sequences bs
JOIN staging.import_batch b ON bs.batch_id = b.batch_id
ORDER BY bs.sequence_number DESC;

COMMENT ON VIEW staging.vw_sequence_processing_status IS 'Monitor batch sequence processing status and identify stuck sequences';

-- Function to find the next expected sequence number (for Sequential Completion Manager)
CREATE OR REPLACE FUNCTION staging.get_next_expected_sequence()
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    next_seq INTEGER;
BEGIN
    -- Find the first sequence that hasn't been completed yet
    SELECT COALESCE(MIN(sequence_number), 1)
    INTO next_seq
    FROM staging.batch_sequences
    WHERE completed_at IS NULL;

    RETURN next_seq;
END;
$$;

COMMENT ON FUNCTION staging.get_next_expected_sequence IS 'Returns the next sequence number expected for completion (used by SequentialCompletionManager)';

-- Function to detect stuck sequences
CREATE OR REPLACE FUNCTION staging.detect_stuck_sequences(threshold_minutes INTEGER DEFAULT 5)
RETURNS TABLE (
    sequence_number INTEGER,
    assigned_at TIMESTAMPTZ,
    wait_time_minutes REAL,
    claim_count INTEGER,
    worker_id TEXT,
    pending_claims BIGINT,
    processing_claims BIGINT
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT
        bs.sequence_number,
        bs.assigned_at,
        EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - bs.assigned_at))::REAL / 60.0 AS wait_time_minutes,
        bs.claim_count,
        bs.worker_id,
        (SELECT COUNT(*) FROM staging.raw_claims WHERE batch_sequence_number = bs.sequence_number AND processing_status = 'PENDING') AS pending_claims,
        (SELECT COUNT(*) FROM staging.raw_claims WHERE batch_sequence_number = bs.sequence_number AND processing_status = 'PROCESSING') AS processing_claims
    FROM staging.batch_sequences bs
    WHERE bs.completed_at IS NULL
    AND bs.assigned_at < CURRENT_TIMESTAMP - (threshold_minutes || ' minutes')::INTERVAL
    ORDER BY bs.sequence_number ASC;
END;
$$;

COMMENT ON FUNCTION staging.detect_stuck_sequences IS 'Detects sequences that have been waiting too long (default: 5 minutes) - indicates potential worker failure';

-- Add configuration table for FIFO mode
CREATE TABLE IF NOT EXISTS staging.processing_configuration (
    config_key TEXT PRIMARY KEY,
    config_value TEXT NOT NULL,
    description TEXT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

