-- ============================================================================
-- 9. Function: Get Active Rules for Facility
-- ============================================================================

CREATE OR REPLACE FUNCTION claims.get_active_rules_for_facility(
    p_facility_id BIGINT,
    p_execution_level VARCHAR DEFAULT NULL -- 'ENCOUNTER', 'SERVICE_LINE', or NULL for both
) RETURNS TABLE (
    rule_id BIGINT,
    rule_code VARCHAR,
    rule_name VARCHAR,
    template_code VARCHAR,
    execution_order INT,
    execution_level VARCHAR,
    flag_issue_id BIGINT,
    parameter_overrides BYTEA,
    assignment_level VARCHAR
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        vafr.rule_id,
        vafr.rule_code,
        vafr.rule_name,
        vafr.template_code,
        vafr.execution_order,
        vafr.execution_level,
        vafr.flag_issue_id,
        COALESCE(fra.parameter_overrides_encrypted, ora.parameter_overrides_encrypted) AS parameter_overrides,
        vafr.assignment_level
    FROM claims.v_active_facility_rules vafr
    LEFT JOIN claims.facility_rule_assignment fra ON (
        fra.facility_id = vafr.facility_id AND fra.rule_id = vafr.rule_id
    )
    LEFT JOIN claims.organization_rule_assignment ora ON (
        ora.organization_id = vafr.organization_id AND ora.rule_id = vafr.rule_id AND fra.assignment_id IS NULL
    )
    WHERE vafr.facility_id = p_facility_id
    AND vafr.is_enabled = true
    AND (p_execution_level IS NULL OR vafr.execution_level = p_execution_level OR vafr.execution_level = 'BOTH')
    ORDER BY vafr.execution_order;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.get_active_rules_for_facility IS 'Returns all active rules for a facility with parameter overrides';

-- ============================================================================
-- 10. Function: Record Rule Execution Stats
-- ============================================================================

CREATE OR REPLACE FUNCTION claims.record_rule_execution(
    p_rule_id BIGINT,
    p_facility_id BIGINT,
    p_execution_time_ms INT,
    p_triggered BOOLEAN DEFAULT false,
    p_financial_impact NUMERIC DEFAULT NULL,
    p_error BOOLEAN DEFAULT false,
    p_timeout BOOLEAN DEFAULT false
) RETURNS VOID AS $$
BEGIN
    INSERT INTO claims.rule_execution_stats (
        rule_id,
        facility_id,
        stat_date,
        execution_count,
        flag_triggered_count,
        total_execution_time_ms,
        avg_execution_time_ms,
        max_execution_time_ms,
        min_execution_time_ms,
        error_count,
        timeout_count,
        total_financial_impact,
        first_execution_at,
        last_execution_at
    ) VALUES (
        p_rule_id,
        p_facility_id,
        CURRENT_DATE,
        1,
        CASE WHEN p_triggered THEN 1 ELSE 0 END,
        p_execution_time_ms,
        p_execution_time_ms,
        p_execution_time_ms,
        p_execution_time_ms,
        CASE WHEN p_error THEN 1 ELSE 0 END,
        CASE WHEN p_timeout THEN 1 ELSE 0 END,
        COALESCE(p_financial_impact, 0),
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP
    )
    ON CONFLICT (rule_id, facility_id, stat_date)
    DO UPDATE SET
        execution_count = claims.rule_execution_stats.execution_count + 1,
        flag_triggered_count = claims.rule_execution_stats.flag_triggered_count + CASE WHEN p_triggered THEN 1 ELSE 0 END,
        total_execution_time_ms = claims.rule_execution_stats.total_execution_time_ms + p_execution_time_ms,
        avg_execution_time_ms = (claims.rule_execution_stats.total_execution_time_ms + p_execution_time_ms) / (claims.rule_execution_stats.execution_count + 1),
        max_execution_time_ms = GREATEST(claims.rule_execution_stats.max_execution_time_ms, p_execution_time_ms),
        min_execution_time_ms = LEAST(claims.rule_execution_stats.min_execution_time_ms, p_execution_time_ms),
        error_count = claims.rule_execution_stats.error_count + CASE WHEN p_error THEN 1 ELSE 0 END,
        timeout_count = claims.rule_execution_stats.timeout_count + CASE WHEN p_timeout THEN 1 ELSE 0 END,
        total_financial_impact = claims.rule_execution_stats.total_financial_impact + COALESCE(p_financial_impact, 0),
        last_execution_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.record_rule_execution IS 'Records execution statistics for a rule (upserts daily stats)';

-- ============================================================================
-- Source: 047_add_test_facility_rule_assignments.sql
-- ============================================================================

-- Migration: 047_add_test_facility_rule_assignments
-- Description: Add helper functions and views for facility rule assignments
-- Date: 2025-11-05
-- Purpose: Enable per-facility rule configuration
-- Note: Test data insertion removed to support fresh installs without pre-existing facilities

-- ============================================================================
-- 4. View: Rule assignment summary by facility
-- ============================================================================

CREATE OR REPLACE VIEW claims.v_facility_rule_summary AS
SELECT
    f.facility_id,
    f.facility_code,
    f.facility_name,
    f.organization_id,
    o.organization_name,
    COUNT(DISTINCT CASE WHEN vafr.is_enabled THEN vafr.rule_id END) as enabled_rules_count,
    COUNT(DISTINCT rd.rule_id) as total_rules_count,
    STRING_AGG(
        DISTINCT CASE WHEN vafr.is_enabled THEN vafr.rule_code END,
        ', ' ORDER BY CASE WHEN vafr.is_enabled THEN vafr.rule_code END
    ) as enabled_rules
FROM claims.facility f
INNER JOIN claims.organization o ON f.organization_id = o.organization_id
CROSS JOIN claims.rule_definition rd
LEFT JOIN claims.v_active_facility_rules vafr ON (
    vafr.facility_id = f.facility_id
    AND vafr.rule_id = rd.rule_id
)
WHERE rd.is_active = true
GROUP BY f.facility_id, f.facility_code, f.facility_name, f.organization_id, o.organization_name
ORDER BY f.facility_code;

COMMENT ON VIEW claims.v_facility_rule_summary IS 'Summary of enabled rules per facility';

-- ============================================================================
-- 5. Function: Enable rule for facility
-- ============================================================================

CREATE OR REPLACE FUNCTION claims.enable_rule_for_facility(
    p_facility_id BIGINT,
    p_rule_code VARCHAR,
    p_assigned_by VARCHAR DEFAULT 'ADMIN'
) RETURNS VOID AS $$
DECLARE
    v_rule_id BIGINT;
BEGIN
    -- Get rule ID
    SELECT rule_id INTO v_rule_id
    FROM claims.rule_definition
    WHERE rule_code = p_rule_code AND is_active = true;

    IF v_rule_id IS NULL THEN
        RAISE EXCEPTION 'Rule not found: %', p_rule_code;
    END IF;

    -- Insert or update assignment
    INSERT INTO claims.facility_rule_assignment (
        facility_id, rule_id, is_enabled, assigned_by, updated_at, updated_by
    ) VALUES (
        p_facility_id, v_rule_id, true, p_assigned_by, CURRENT_TIMESTAMP, p_assigned_by
    )
    ON CONFLICT (facility_id, rule_id)
    DO UPDATE SET
        is_enabled = true,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = p_assigned_by;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.enable_rule_for_facility IS 'Enable a specific rule for a facility';

-- ============================================================================
-- 6. Function: Disable rule for facility
-- ============================================================================

CREATE OR REPLACE FUNCTION claims.disable_rule_for_facility(
    p_facility_id BIGINT,
    p_rule_code VARCHAR,
    p_assigned_by VARCHAR DEFAULT 'ADMIN'
) RETURNS VOID AS $$
DECLARE
    v_rule_id BIGINT;
BEGIN
    -- Get rule ID
    SELECT rule_id INTO v_rule_id
    FROM claims.rule_definition
    WHERE rule_code = p_rule_code AND is_active = true;

    IF v_rule_id IS NULL THEN
        RAISE EXCEPTION 'Rule not found: %', p_rule_code;
    END IF;

    -- Insert or update assignment
    INSERT INTO claims.facility_rule_assignment (
        facility_id, rule_id, is_enabled, assigned_by, updated_at, updated_by
    ) VALUES (
        p_facility_id, v_rule_id, false, p_assigned_by, CURRENT_TIMESTAMP, p_assigned_by
    )
    ON CONFLICT (facility_id, rule_id)
    DO UPDATE SET
        is_enabled = false,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = p_assigned_by;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.disable_rule_for_facility IS 'Disable a specific rule for a facility';

-- ============================================================================
-- 7. Function: Enable rule for organization (all facilities)
-- ============================================================================

CREATE OR REPLACE FUNCTION claims.enable_rule_for_organization(
    p_organization_id BIGINT,
    p_rule_code VARCHAR,
    p_assigned_by VARCHAR DEFAULT 'ADMIN'
) RETURNS VOID AS $$
DECLARE
    v_rule_id BIGINT;
BEGIN
    -- Get rule ID
    SELECT rule_id INTO v_rule_id
    FROM claims.rule_definition
    WHERE rule_code = p_rule_code AND is_active = true;

    IF v_rule_id IS NULL THEN
        RAISE EXCEPTION 'Rule not found: %', p_rule_code;
    END IF;

    -- Insert or update assignment
    INSERT INTO claims.organization_rule_assignment (
        organization_id, rule_id, is_enabled, assigned_by, updated_at, updated_by
    ) VALUES (
        p_organization_id, v_rule_id, true, p_assigned_by, CURRENT_TIMESTAMP, p_assigned_by
    )
    ON CONFLICT (organization_id, rule_id)
    DO UPDATE SET
        is_enabled = true,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = p_assigned_by;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.enable_rule_for_organization IS 'Enable a specific rule for all facilities in an organization';

-- ============================================================================
-- 8. Function: Get rules for facility (debugging)
-- ============================================================================

CREATE OR REPLACE FUNCTION claims.debug_facility_rules(
    p_facility_id BIGINT
) RETURNS TABLE (
    rule_code VARCHAR,
    rule_name VARCHAR,
    is_enabled BOOLEAN,
    assignment_level VARCHAR,
    execution_order INT
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        vafr.rule_code,
        vafr.rule_name,
        vafr.is_enabled,
        vafr.assignment_level,
        vafr.execution_order
    FROM claims.v_active_facility_rules vafr
    WHERE vafr.facility_id = p_facility_id
    ORDER BY vafr.execution_order;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.debug_facility_rules IS 'Debug: Show all rules and their status for a facility';

-- ============================================================================
-- Source: 048_add_rule_templates.sql
-- ============================================================================

-- Migration: Add Rule Templates (Phase 3)
-- Description: Add template definitions and example template-based rules
-- Date: 2025-11-05

-- Insert template definitions
DO $$
DECLARE
    v_threshold_template_id BIGINT;
    v_duplicate_template_id BIGINT;
    v_missing_field_template_id BIGINT;
    v_field_pattern_template_id BIGINT;
    v_cross_field_template_id BIGINT;
BEGIN
    -- 1. THRESHOLD Template
    INSERT INTO claims.rule_template (
        template_code,
        template_name,
        rust_struct_name,
        parameter_schema,
        execution_level,
        is_active
    ) VALUES (
        'THRESHOLD',
        'Threshold Comparison Rule',
        'ThresholdRule',
        jsonb_build_object(
            'parameters', jsonb_build_array(
                jsonb_build_object(
                    'name', 'field',
                    'type', 'string',
                    'required', true,
                    'description', 'Field to check (e.g., total_charge, units)',
                    'enum', jsonb_build_array('total_charge', 'units', 'allowed_amount', 'patient_responsibility')
                ),
                jsonb_build_object(
                    'name', 'operator',
                    'type', 'string',
                    'required', true,
                    'description', 'Comparison operator',
                    'enum', jsonb_build_array('>', '>=', '<', '<=', '==', '!=')
                ),
                jsonb_build_object(
                    'name', 'threshold',
                    'type', 'number',
                    'required', true,
                    'description', 'Threshold value to compare against'
                ),
                jsonb_build_object(
                    'name', 'min_threshold',
                    'type', 'number',
                    'required', false,
                    'description', 'Optional minimum threshold for range checks'
                ),
                jsonb_build_object(
                    'name', 'max_threshold',
                    'type', 'number',
                    'required', false,
                    'description', 'Optional maximum threshold for range checks'
                )
            )
        ),
        'BOTH',
        true
    ) ON CONFLICT (template_code) DO UPDATE SET template_name = EXCLUDED.template_name RETURNING template_id INTO v_threshold_template_id;

    -- 2. DUPLICATE Template
    INSERT INTO claims.rule_template (
        template_code,
        template_name,
        rust_struct_name,
        parameter_schema,
        execution_level,
        is_active
    ) VALUES (
        'DUPLICATE',
        'Duplicate Detection Rule',
        'DuplicateRule',
        jsonb_build_object(
            'parameters', jsonb_build_array(
                jsonb_build_object(
                    'name', 'table',
                    'type', 'string',
                    'required', true,
                    'description', 'Table to check for duplicates',
                    'enum', jsonb_build_array('service_line', 'encounter', 'provider')
                ),
                jsonb_build_object(
                    'name', 'match_fields',
                    'type', 'array',
                    'required', true,
                    'description', 'Fields that must match to be considered duplicate'
                ),
                jsonb_build_object(
                    'name', 'scope',
                    'type', 'string',
                    'required', false,
                    'default', 'encounter',
                    'description', 'Scope of duplicate check',
                    'enum', jsonb_build_array('encounter', 'patient', 'facility')
                ),
                jsonb_build_object(
                    'name', 'time_window_days',
                    'type', 'number',
                    'required', false,
                    'default', 0,
                    'description', 'Number of days to look back for duplicates'
                ),
                jsonb_build_object(
                    'name', 'case_sensitive',
                    'type', 'boolean',
                    'required', false,
                    'default', false,
                    'description', 'Whether string comparisons should be case-sensitive'
                )
            )
        ),
        'BOTH',
        true
    ) ON CONFLICT (template_code) DO UPDATE SET template_name = EXCLUDED.template_name RETURNING template_id INTO v_duplicate_template_id;

    -- 3. MISSING_FIELD Template
    INSERT INTO claims.rule_template (
        template_code,
        template_name,
        rust_struct_name,
        parameter_schema,
        execution_level,
        is_active
    ) VALUES (
        'MISSING_FIELD',
        'Missing Required Field Rule',
        'MissingFieldRule',
        jsonb_build_object(
            'parameters', jsonb_build_array(
                jsonb_build_object(
                    'name', 'fields',
                    'type', 'array',
                    'required', true,
                    'description', 'List of required fields to check'
                ),
                jsonb_build_object(
                    'name', 'check_empty',
                    'type', 'boolean',
                    'required', false,
                    'default', true,
                    'description', 'Also flag empty strings (not just NULL)'
                ),
                jsonb_build_object(
                    'name', 'execution_level',
                    'type', 'string',
                    'required', false,
                    'default', 'service_line',
                    'description', 'Where to check',
                    'enum', jsonb_build_array('service_line', 'encounter')
                )
            )
        ),
        'BOTH',
        true
    ) ON CONFLICT (template_code) DO UPDATE SET template_name = EXCLUDED.template_name RETURNING template_id INTO v_missing_field_template_id;

    -- 4. FIELD_PATTERN Template
    INSERT INTO claims.rule_template (
        template_code,
        template_name,
        rust_struct_name,
        parameter_schema,
        execution_level,
        is_active
    ) VALUES (
        'FIELD_PATTERN',
        'Field Pattern Validation Rule',
        'FieldPatternRule',
        jsonb_build_object(
            'parameters', jsonb_build_array(
                jsonb_build_object(
                    'name', 'field',
                    'type', 'string',
                    'required', true,
                    'description', 'Field to validate'
                ),
                jsonb_build_object(
                    'name', 'pattern',
                    'type', 'string',
                    'required', true,
                    'description', 'Regex pattern to match'
                ),
                jsonb_build_object(
                    'name', 'invert_match',
                    'type', 'boolean',
                    'required', false,
                    'default', false,
                    'description', 'If true, flag when pattern DOES match'
                ),
                jsonb_build_object(
                    'name', 'case_sensitive',
                    'type', 'boolean',
                    'required', false,
                    'default', true,
                    'description', 'Whether regex should be case-sensitive'
                ),
                jsonb_build_object(
                    'name', 'allow_null',
                    'type', 'boolean',
                    'required', false,
                    'default', true,
                    'description', 'If true, NULL/empty values pass validation'
                ),
                jsonb_build_object(
                    'name', 'execution_level',
                    'type', 'string',
                    'required', false,
                    'default', 'service_line',
                    'enum', jsonb_build_array('service_line', 'encounter')
                )
            )
        ),
        'BOTH',
        true
    ) ON CONFLICT (template_code) DO UPDATE SET template_name = EXCLUDED.template_name RETURNING template_id INTO v_field_pattern_template_id;

    -- 5. CROSS_FIELD Template
    INSERT INTO claims.rule_template (
        template_code,
        template_name,
        rust_struct_name,
        parameter_schema,
        execution_level,
        is_active
    ) VALUES (
        'CROSS_FIELD',
        'Cross-Field Comparison Rule',
        'CrossFieldRule',
        jsonb_build_object(
            'parameters', jsonb_build_array(
                jsonb_build_object(
                    'name', 'field1',
                    'type', 'string',
                    'required', true,
                    'description', 'First field to compare'
                ),
                jsonb_build_object(
                    'name', 'operator',
                    'type', 'string',
                    'required', true,
                    'description', 'Comparison operator',
                    'enum', jsonb_build_array('>', '>=', '<', '<=', '==', '!=')
                ),
                jsonb_build_object(
                    'name', 'field2',
                    'type', 'string',
                    'required', true,
                    'description', 'Second field to compare'
                ),
                jsonb_build_object(
                    'name', 'execution_level',
                    'type', 'string',
                    'required', false,
                    'default', 'service_line',
                    'enum', jsonb_build_array('service_line', 'encounter')
                )
            )
        ),
        'BOTH',
        true
    ) ON CONFLICT (template_code) DO UPDATE SET template_name = EXCLUDED.template_name RETURNING template_id INTO v_cross_field_template_id;

    -- Example template-based rules

    -- Example 1: High charge threshold rule
    INSERT INTO claims.rule_definition (
        rule_code,
        rule_name,
        template_id,
        rule_parameters_encrypted,
        flag_issue_id,
        execution_order,
        execution_level,
        is_active
    ) VALUES (
        'HIGH_CHARGE_THRESHOLD',
        'Flag charges over $10,000',
        v_threshold_template_id,
        pgp_sym_encrypt(
            '{"field": "total_charge", "operator": ">", "threshold": 10000}'::text,
            (SELECT current_setting('app.rule_encryption_key', true))
        ),
        (SELECT issue_id FROM claims.flag_issue WHERE issue_code = 'HIGH_CHARGE'),
        70,
        'SERVICE_LINE',
        false  -- Disabled by default, enable per facility as needed
    );

    -- Example 2: CPT code format validation
    INSERT INTO claims.rule_definition (
        rule_code,
        rule_name,
        template_id,
        rule_parameters_encrypted,
        flag_issue_id,
        execution_order,
        execution_level,
        is_active
    ) VALUES (
        'CPT_CODE_FORMAT',
        'Validate CPT code is 5 digits',
        v_field_pattern_template_id,
        pgp_sym_encrypt(
            '{"field": "procedure_code", "pattern": "^\\d{5}$", "allow_null": false}'::text,
            (SELECT current_setting('app.rule_encryption_key', true))
        ),
        (SELECT issue_id FROM claims.flag_issue WHERE issue_code = 'INVALID_CODE_FORMAT'),
        80,
        'SERVICE_LINE',
        false
    ) ON CONFLICT (rule_code) DO NOTHING;

    -- Example 3: Service date range validation
    INSERT INTO claims.rule_definition (
        rule_code,
        rule_name,
        template_id,
        rule_parameters_encrypted,
        flag_issue_id,
        execution_order,
        execution_level,
        is_active
    ) VALUES (
        'INVALID_DATE_RANGE',
        'Flag when service_to_date < service_from_date',
        v_cross_field_template_id,
        pgp_sym_encrypt(
            '{"field1": "service_to_date", "operator": "<", "field2": "service_from_date"}'::text,
            (SELECT current_setting('app.rule_encryption_key', true))
        ),
        (SELECT issue_id FROM claims.flag_issue WHERE issue_code = 'INVALID_DATE'),
        90,
        'SERVICE_LINE',
        false
    ) ON CONFLICT (rule_code) DO NOTHING;

    -- Example 4: Missing required billing fields
    INSERT INTO claims.rule_definition (
        rule_code,
        rule_name,
        template_id,
        rule_parameters_encrypted,
        flag_issue_id,
        execution_order,
        execution_level,
        is_active
    ) VALUES (
        'MISSING_BILLING_FIELDS',
        'Check for missing required billing fields',
        v_missing_field_template_id,
        pgp_sym_encrypt(
            '{"fields": ["billing_provider_id", "date_of_service", "total_charge"], "execution_level": "encounter"}'::text,
            (SELECT current_setting('app.rule_encryption_key', true))
        ),
        (SELECT issue_id FROM claims.flag_issue WHERE issue_code = 'MISSING_REQUIRED_FIELD'),
        100,
        'ENCOUNTER',
        false
    ) ON CONFLICT (rule_code) DO NOTHING;

    -- Example 5: Duplicate service line detection (template-based)
    INSERT INTO claims.rule_definition (
        rule_code,
        rule_name,
        template_id,
        rule_parameters_encrypted,
        flag_issue_id,
        execution_order,
        execution_level,
        is_active
    ) VALUES (
        'DUPLICATE_SERVICE_TEMPLATE',
        'Detect duplicate service lines (configurable)',
        v_duplicate_template_id,
        pgp_sym_encrypt(
            '{"table": "service_line", "match_fields": ["procedure_code", "service_from_date", "units"], "scope": "encounter"}'::text,
            (SELECT current_setting('app.rule_encryption_key', true))
        ),
        (SELECT issue_id FROM claims.flag_issue WHERE issue_code = 'DUPLICATE_SERVICE'),
        110,
        'SERVICE_LINE',
        false
    ) ON CONFLICT (rule_code) DO NOTHING;

    RAISE NOTICE 'Phase 3 complete: Added 5 rule templates and 5 example rules';
END $$;

