-- ============================================================================
-- Source: 049_add_flag_issue_helpers.sql
-- ============================================================================

-- Migration 049: Add helper functions for FlagIssueType mapping
-- Phase 4: Proper database-driven flag type resolution
--
-- This migration adds:
-- 1. Helper function to get FlagIssueType enum name from issue_code
-- 2. Helper view for rule loading with proper flag type mapping

-- Helper function: Get FlagIssueType enum name from issue_code
-- This maps the database issue_code to the Rust enum variant name
CREATE OR REPLACE FUNCTION claims.get_flag_issue_type_name(p_issue_code TEXT)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    -- Map issue_code to Rust FlagIssueType enum name
    -- The enum names follow the pattern: Category + CamelCaseDescription
    RETURN CASE p_issue_code
        -- Coding (COD) issues
        WHEN 'COD_BUNDLED' THEN 'CodBundledService'
        WHEN 'COD_INCORRECT' THEN 'CodIncorrectProcedureCode'
        WHEN 'COD_MISSED' THEN 'CodMissedCharge'
        WHEN 'COD_UPCODING' THEN 'CodUpcoding'
        WHEN 'COD_DOWNCODING' THEN 'CodDowncoding'
        WHEN 'COD_UNBUNDLING' THEN 'CodUnbundling'
        WHEN 'COD_BILATERAL' THEN 'CodBilateralProcedure'
        WHEN 'COD_GLOBAL_PERIOD' THEN 'CodGlobalPeriod'

        -- Modifier (MOD) issues
        WHEN 'MOD_MISSING_REQUIRED' THEN 'ModMissingRequired'
        WHEN 'MOD_INCORRECT' THEN 'ModIncorrect'
        WHEN 'MOD_CONFLICTING' THEN 'ModConflicting'
        WHEN 'MOD_UNNECESSARY' THEN 'ModUnnecessary'
        WHEN 'MOD_MISSING_59' THEN 'ModMissing59'
        WHEN 'MOD_MISSING_25' THEN 'ModMissing25'

        -- Quantity/Units (QTY) issues
        WHEN 'QTY_UNITS_EXCEED_MAX' THEN 'QtyUnitsExceedMaximum'
        WHEN 'QTY_UNITS_INCONSISTENT' THEN 'QtyUnitsInconsistent'
        WHEN 'QTY_MULTIPLE_UNITS' THEN 'QtyMultipleUnitsNotSupported'
        WHEN 'QTY_TIME_BASED' THEN 'QtyTimeBasedCoding'

        -- Diagnosis (DX) issues
        WHEN 'DX_UNSPECIFIED' THEN 'DxUnspecifiedWhenSpecificAvailable'
        WHEN 'DX_MISSING_SPECIFICITY' THEN 'DxMissingSpecificity'
        WHEN 'DX_NOT_SUPPORT' THEN 'DxDoesNotSupportProcedure'
        WHEN 'DX_CHRONOLOGY' THEN 'DxChronologyIssue'
        WHEN 'DX_LATERALITY' THEN 'DxLateralityMismatch'
        WHEN 'DX_MANIFESTATION' THEN 'DxManifestationFirst'

        -- Documentation (DOC) issues
        WHEN 'DOC_INSUFFICIENT' THEN 'DocInsufficientDocumentation'
        WHEN 'DOC_MISSING_REQUIRED' THEN 'DocMissingRequiredElements'
        WHEN 'DOC_INCONSISTENT' THEN 'DocInconsistentDocumentation'
        WHEN 'DOC_MISSING_TIME' THEN 'DocMissingTimeElements'
        WHEN 'DOC_SIGNATURE' THEN 'DocSignatureIssue'

        -- Medical Necessity (MED) issues
        WHEN 'MED_NOT_REASONABLE' THEN 'MedNotReasonableOrNecessary'
        WHEN 'MED_EXPERIMENTAL' THEN 'MedExperimentalInvestigational'
        WHEN 'MED_FREQUENCY' THEN 'MedFrequencyLimitation'
        WHEN 'MED_COVERAGE' THEN 'MedCoverageRequirements'

        -- Place of Service (POS) issues
        WHEN 'POS_INCONSISTENT' THEN 'PosInconsistentWithProcedure'
        WHEN 'POS_NOT_COVERED' THEN 'PosNotCoveredForService'

        -- Provider (PRV) issues
        WHEN 'PRV_CREDENTIALS' THEN 'PrvCredentialsQualification'
        WHEN 'PRV_SPECIALTY' THEN 'PrvSpecialtyMismatch'
        WHEN 'PRV_SUPERVISION' THEN 'PrvSupervisionRequirement'

        -- Other (OTH) issues
        WHEN 'OTH_DUPLICATE_SERVICE' THEN 'OthDuplicateService'
        WHEN 'OTH_TIMELY_FILING' THEN 'OthTimelyFiling'
        WHEN 'OTH_COORDINATION_BENEFITS' THEN 'OthCoordinationOfBenefits'
        WHEN 'OTH_PRIOR_AUTH' THEN 'OthPriorAuthorizationRequired'

        -- Default fallback
        ELSE 'OthDuplicateService'
    END;
END;
$$;

COMMENT ON FUNCTION claims.get_flag_issue_type_name(TEXT) IS
'Maps database issue_code to Rust FlagIssueType enum name for rule loading';

-- Helper view: Rule definitions with FlagIssueType enum names
-- This view is used by the rule loader to get the proper enum names
CREATE OR REPLACE VIEW claims.v_rule_definitions_with_flag_types AS
SELECT
    rd.rule_id,
    rd.rule_code,
    rd.rule_name,
    rd.template_id,
    rt.template_code,
    rt.template_name,
    rd.flag_issue_id,
    fi.issue_code,
    claims.get_flag_issue_type_name(fi.issue_code) AS flag_issue_type_name,
    rd.execution_order,
    rd.execution_level,
    rd.is_active,
    rd.created_at,
    rd.updated_at,
    rd.rule_parameters_encrypted
FROM claims.rule_definition rd
INNER JOIN claims.flag_issue fi ON rd.flag_issue_id = fi.issue_id
LEFT JOIN claims.rule_template rt ON rd.template_id = rt.template_id
WHERE rd.is_active = true
ORDER BY rd.execution_order;

COMMENT ON VIEW claims.v_rule_definitions_with_flag_types IS
'Rule definitions with FlagIssueType enum names for easy loading in Rust';

-- Helper view: Active facility rules with flag type names
CREATE OR REPLACE VIEW claims.v_active_facility_rules_with_types AS
SELECT
    fa.assignment_id AS facility_rule_id,
    fa.facility_id,
    fa.rule_id,
    rd.rule_code,
    rd.rule_name,
    rt.template_code,
    fi.issue_code,
    claims.get_flag_issue_type_name(fi.issue_code) AS flag_issue_type_name,
    rd.execution_order,
    rd.execution_level,
    fa.parameter_overrides_encrypted,
    fa.is_enabled AS facility_override_active,
    rd.is_active AS rule_active
FROM claims.facility_rule_assignment fa
INNER JOIN claims.rule_definition rd ON fa.rule_id = rd.rule_id
INNER JOIN claims.flag_issue fi ON rd.flag_issue_id = fi.issue_id
LEFT JOIN claims.rule_template rt ON rd.template_id = rt.template_id
WHERE fa.is_enabled = true
  AND rd.is_active = true
ORDER BY fa.facility_id, rd.execution_order;

COMMENT ON VIEW claims.v_active_facility_rules_with_types IS
'Active facility rule assignments with FlagIssueType enum names';

-- Add index for faster lookups
CREATE INDEX IF NOT EXISTS idx_rule_definition_active ON claims.rule_definition(is_active) WHERE is_active = true;
CREATE INDEX IF NOT EXISTS idx_facility_rule_active ON claims.facility_rule_assignment(is_enabled, facility_id) WHERE is_enabled = true;

-- Grant permissions (conditional - only if role exists)
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'pro_app') THEN
        GRANT EXECUTE ON FUNCTION claims.get_flag_issue_type_name(TEXT) TO pro_app;
        GRANT SELECT ON claims.v_rule_definitions_with_flag_types TO pro_app;
        GRANT SELECT ON claims.v_active_facility_rules_with_types TO pro_app;
    END IF;
END $$;

-- ============================================================================
-- Source: 050_add_performance_indexes.sql
-- ============================================================================

-- Migration: Add Performance Indexes for Rules Engine
-- Phase 6 Critical Optimizations
-- Expected Impact: 90%+ improvement on duplicate detection and batch queries

-- ============================================================================
-- DUPLICATE DETECTION OPTIMIZATION
-- ============================================================================
-- These indexes support the duplicate detection rule which queries:
-- "SELECT COUNT(*) FROM service_line WHERE encounter_id = ? AND procedure_code = ?"

-- Composite index for duplicate detection (most critical)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_service_line_duplicate_detection
ON claims.service_line (encounter_id, procedure_code)
WHERE line_status = 'ACTIVE';

-- Covering index with modifiers for modifier-aware duplicate detection
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_service_line_duplicate_with_modifiers
ON claims.service_line (encounter_id, procedure_code, procedure_modifier_1, procedure_modifier_2)
INCLUDE (service_line_id, line_item_charge_amount)
WHERE line_status = 'ACTIVE';

-- ============================================================================
-- PROVIDER LOOKUP OPTIMIZATION
-- ============================================================================
-- Supports queries like: "SELECT provider_id FROM provider WHERE npi = ?"

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_provider_npi_lookup
ON claims.provider (npi)
INCLUDE (provider_id, last_name, first_name, provider_type);

-- ============================================================================
-- ENCOUNTER BATCH PROCESSING OPTIMIZATION
-- ============================================================================
-- Supports loading diagnosis codes for multiple encounters efficiently

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_diagnosis_code_encounter_batch
ON claims.encounter_diagnosis (encounter_id)
INCLUDE (diagnosis_code, sequence_number);

-- ============================================================================
-- SERVICE LINE BATCH LOADING OPTIMIZATION
-- ============================================================================
-- Supports batch loading service lines by encounter_id with all needed fields

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_service_line_encounter_batch
ON claims.service_line (encounter_id, line_number)
INCLUDE (procedure_code, procedure_modifier_1, service_unit_count, line_item_charge_amount, service_date_from)
WHERE line_status = 'ACTIVE';

-- ============================================================================
-- RULE EXECUTION LOG OPTIMIZATION (for execution_planner.rs)
-- ============================================================================
-- Supports loading historical statistics for rule execution planning
-- Query pattern: "SELECT flag_type, AVG(...) FROM rule_execution_log GROUP BY flag_type"

-- Note: This table doesn't exist yet, but when it does, this index will be ready
-- CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_rule_execution_log_stats
-- ON claims.rule_execution_log (flag_type)
-- INCLUDE (flag_created, financial_impact, execution_time_ms);

-- ============================================================================
-- FACILITY RULE CONFIGURATION OPTIMIZATION
-- ============================================================================
-- Supports queries: "SELECT * FROM facility_rule_assignment WHERE facility_id = ? AND is_enabled = true"

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_facility_rule_config_lookup
ON claims.facility_rule_assignment (facility_id, is_enabled)
INCLUDE (rule_id, parameter_overrides_encrypted);

-- ============================================================================
-- STATISTICS AND VERIFICATION
-- ============================================================================

-- ============================================================================
-- BATCH PROCESSING OPTIMIZATION (PHASE 6 MEDIUM-VALUE)
-- ============================================================================
-- Supports batch completion queries that count by batch_id and processing_status
-- Query pattern: "SELECT batch_id, COUNT(*) FILTER (WHERE processing_status = ...)
--                 FROM raw_claims WHERE batch_id = ANY($1) GROUP BY batch_id"

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_raw_claims_batch_status
ON staging.raw_claims (batch_id, processing_status)
INCLUDE (raw_claim_id);

-- ============================================================================
-- STATISTICS AND ANALYSIS
-- ============================================================================

-- Analyze tables to update statistics for query planner
ANALYZE claims.service_line;
ANALYZE claims.provider;
ANALYZE claims.encounter_diagnosis;
ANALYZE claims.facility_rule_assignment;
ANALYZE staging.raw_claims;

-- Display index sizes for monitoring
DO $$
BEGIN
    RAISE NOTICE '=== Index Creation Complete ===';
    RAISE NOTICE 'Index sizes:';

    -- This will be visible in migration logs
    PERFORM pg_size_pretty(pg_relation_size('claims.idx_service_line_duplicate_detection'));
END $$;

-- ============================================================================
-- MIGRATION NOTES
-- ============================================================================
--
-- CONCURRENTLY option: Indexes are built without blocking writes
-- WHERE clauses: Partial indexes only include active records (smaller, faster)
-- INCLUDE: Covering indexes allow index-only scans (no table access needed)
--
-- Expected Performance Improvements:
-- - Duplicate detection: 50-200x faster (table scan → index lookup)
-- - Provider lookups: 100-500x faster (table scan → index lookup)
-- - Batch processing: 10-50x faster (sorted access, covering index)
-- - Diagnosis loading: 20-100x faster (index scan vs sequential)
-- - Batch completion queries: 10-50x faster (grouped aggregation with index)
--
-- Disk Space Impact:
-- - Estimated 50-200 MB per index (depends on table size)
-- - Total: ~600 MB - 1.2 GB for all indexes (7 indexes total)
-- - Trade-off: Disk space for 90%+ query performance improvement
--
-- Maintenance:
-- - Indexes are automatically maintained by PostgreSQL
-- - VACUUM ANALYZE recommended after large data loads
-- - Monitor index bloat with pg_stat_user_indexes
-- ============================================================================

-- ============================================================================
-- Source: 051_add_rule_execution_stats.sql
-- ============================================================================

-- Migration: Add Rule Execution Statistics Views and Functions
-- Phase 8: Historical statistics views for execution planner
-- Note: Table already created by migration 046, this adds helper views/functions
-- Expected Impact: 20-30% better rule ordering with real historical data

-- ============================================================================
-- AGGREGATED STATISTICS VIEW (FOR QUICK LOOKUPS)
-- ============================================================================
-- Pre-computed statistics for fast execution planner initialization
-- Uses the existing rule_execution_stats table from migration 046

CREATE MATERIALIZED VIEW IF NOT EXISTS claims.rule_execution_stats_summary AS
SELECT
    r.rule_id,
    rd.rule_code,
    r.facility_id,
    r.stat_date,
    r.execution_count,
    r.flag_triggered_count,

    -- Trigger rate
    CASE WHEN r.execution_count > 0
         THEN CAST(r.flag_triggered_count AS DECIMAL) / r.execution_count
         ELSE 0
    END as trigger_rate,

    -- Average financial impact (total / triggered count)
    CASE WHEN r.flag_triggered_count > 0
         THEN r.total_financial_impact / r.flag_triggered_count
         ELSE 0
    END as avg_financial_impact_per_flag,

    -- Average execution time
    r.avg_execution_time_ms,
    r.max_execution_time_ms,
    r.min_execution_time_ms,

    -- Error metrics
    r.error_count,
    r.timeout_count,

    -- Time range
    r.first_execution_at,
    r.last_execution_at
FROM claims.rule_execution_stats r
INNER JOIN claims.rule_definition rd ON r.rule_id = rd.rule_id
WHERE r.stat_date >= CURRENT_DATE - INTERVAL '30 days'
  AND r.execution_count >= 10;

-- Index on materialized view for fast lookups
CREATE UNIQUE INDEX IF NOT EXISTS idx_rule_execution_stats_summary_pk
ON claims.rule_execution_stats_summary (rule_id, facility_id, stat_date);

CREATE INDEX IF NOT EXISTS idx_rule_execution_stats_summary_trigger_rate
ON claims.rule_execution_stats_summary (trigger_rate DESC)
WHERE trigger_rate > 0;

-- ============================================================================
-- REFRESH FUNCTION (Call periodically)
-- ============================================================================
-- Refresh materialized view to keep statistics current

CREATE OR REPLACE FUNCTION claims.refresh_rule_execution_stats()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY claims.rule_execution_stats_summary;
    RAISE NOTICE 'Rule execution stats summary refreshed';
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.refresh_rule_execution_stats() IS
'Refresh the rule execution statistics summary materialized view';

-- ============================================================================
-- CLEANUP FUNCTION (Archive old data)
-- ============================================================================
-- Keep last 90 days of detailed stats, delete older data

CREATE OR REPLACE FUNCTION claims.cleanup_old_rule_execution_stats()
RETURNS INTEGER AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM claims.rule_execution_stats
    WHERE stat_date < CURRENT_DATE - INTERVAL '90 days';

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RAISE NOTICE 'Deleted % old rule execution stat records', deleted_count;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION claims.cleanup_old_rule_execution_stats() IS
'Delete rule execution statistics older than 90 days';

-- ============================================================================
-- HELPER VIEW: Latest Statistics by Rule
-- ============================================================================
-- Quick lookup for most recent execution stats per rule

CREATE OR REPLACE VIEW claims.v_latest_rule_execution_stats AS
SELECT DISTINCT ON (r.rule_id, r.facility_id)
    r.rule_id,
    rd.rule_code,
    rd.rule_name,
    r.facility_id,
    r.stat_date,
    r.execution_count,
    r.flag_triggered_count,
    r.avg_execution_time_ms,
    r.total_financial_impact,
    r.error_count,
    r.timeout_count,
    r.last_execution_at
FROM claims.rule_execution_stats r
INNER JOIN claims.rule_definition rd ON r.rule_id = rd.rule_id
ORDER BY r.rule_id, r.facility_id, r.stat_date DESC;

COMMENT ON VIEW claims.v_latest_rule_execution_stats IS
'Latest execution statistics for each rule and facility combination';

-- ============================================================================
-- GRANT PERMISSIONS
-- ============================================================================
-- Grant access to application role if it exists

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'pro_app') THEN
        GRANT SELECT ON claims.rule_execution_stats_summary TO pro_app;
        GRANT SELECT ON claims.v_latest_rule_execution_stats TO pro_app;
        GRANT EXECUTE ON FUNCTION claims.refresh_rule_execution_stats() TO pro_app;
        GRANT EXECUTE ON FUNCTION claims.cleanup_old_rule_execution_stats() TO pro_app;
    END IF;
END $$;

-- ============================================================================
-- INITIAL ANALYSIS
-- ============================================================================

ANALYZE claims.rule_execution_stats;

-- ============================================================================
-- MIGRATION NOTES
-- ============================================================================
--
-- Purpose: Enable intelligent rule ordering based on historical performance
--
-- Usage:
-- 1. Rust code logs executions via record_rule_execution() from migration 046
-- 2. Execution planner reads from rule_execution_stats_summary view
-- 3. Materialized view refreshed periodically (e.g., hourly)
-- 4. Old data cleaned up after 90 days
--
-- Performance:
-- - Materialized view provides O(1) lookup for planner initialization
-- - Indexes enable fast filtering by trigger rate and financial impact
-- - Cleanup function prevents unbounded growth
--
-- Maintenance:
-- - Refresh materialized view: SELECT claims.refresh_rule_execution_stats();
-- - Cleanup old data: SELECT claims.cleanup_old_rule_execution_stats();
-- - Schedule both in cron or application code
--
-- ============================================================================

-- ============================================================================
-- Source: 052_add_npi_registry_link.sql
-- ============================================================================

-- Migration: 052_add_npi_registry_link
-- Description: Add NPI Registry link column to provider table for direct NPPES API access
-- Date: 2025-11-13

-- Add npi_registry_link column to provider table
-- This will store the direct link to the NPPES NPI Registry API for each provider
ALTER TABLE claims.provider
ADD COLUMN IF NOT EXISTS npi_registry_link TEXT;

-- Add comment explaining the column
COMMENT ON COLUMN claims.provider.npi_registry_link IS
'Direct link to NPPES NPI Registry API for this provider. Format: https://nppesapi.cms.hhs.gov/api/?version=2.1&number={NPI}. Auto-populated during NPI enrichment.';

-- Add index for faster lookups if needed (though not commonly queried)
CREATE INDEX IF NOT EXISTS idx_provider_npi_link
ON claims.provider(npi_registry_link)
WHERE npi_registry_link IS NOT NULL;

-- Backfill existing providers with NPI links
-- This generates the link for all existing providers that have an NPI
UPDATE claims.provider
SET npi_registry_link = 'https://nppesapi.cms.hhs.gov/api/?version=2.1&number=' || npi
WHERE npi IS NOT NULL
  AND npi_registry_link IS NULL
  AND LENGTH(npi) = 10;

-- Note: New providers will have npi_registry_link populated automatically during creation
-- and during NPI enrichment when provider data is updated from the NPPES API

-- ============================================================================
-- Source: 053_add_837p_v2_fields.sql
-- ============================================================================

-- Migration 053: Add v2.0.0 837P Comprehensive Data Fields
-- Adds fields for previously unparsed 837P segments:
-- - REF*D9 (Claim Number)
-- - AMT*F5 (Patient Responsibility Amount)
-- - CR1 (Ambulance Transport Information)
-- - PWK (Paperwork/Attachments)
-- - CRC (Condition Indicators)
-- - HCP (Health Care Pricing - at service line level)

-- Add new encounter fields
ALTER TABLE claims.encounter
ADD COLUMN IF NOT EXISTS claim_number VARCHAR(50),
ADD COLUMN IF NOT EXISTS patient_responsibility_amount NUMERIC(10,2),
ADD COLUMN IF NOT EXISTS ambulance_transport_reason_code VARCHAR(10),
ADD COLUMN IF NOT EXISTS ambulance_transport_distance NUMERIC(10,2),
ADD COLUMN IF NOT EXISTS ambulance_patient_weight NUMERIC(10,2),
ADD COLUMN IF NOT EXISTS ambulance_patient_count INTEGER,
ADD COLUMN IF NOT EXISTS paperwork_report_type VARCHAR(10),
ADD COLUMN IF NOT EXISTS paperwork_transmission_code VARCHAR(10),
ADD COLUMN IF NOT EXISTS paperwork_control_number VARCHAR(50),
ADD COLUMN IF NOT EXISTS condition_codes TEXT;

COMMENT ON COLUMN claims.encounter.claim_number IS '837P REF*D9 - Claim Identifier';
COMMENT ON COLUMN claims.encounter.patient_responsibility_amount IS '837P AMT*F5 - Patient Responsibility Amount';
COMMENT ON COLUMN claims.encounter.ambulance_transport_reason_code IS '837P CR1 - Ambulance Transport Reason Code';
COMMENT ON COLUMN claims.encounter.ambulance_transport_distance IS '837P CR1 - Ambulance Transport Distance';
COMMENT ON COLUMN claims.encounter.ambulance_patient_weight IS '837P CR1 - Patient Weight';
COMMENT ON COLUMN claims.encounter.ambulance_patient_count IS '837P CR1 - Patient Count';
COMMENT ON COLUMN claims.encounter.paperwork_report_type IS '837P PWK - Report Type Code';
COMMENT ON COLUMN claims.encounter.paperwork_transmission_code IS '837P PWK - Report Transmission Code';
COMMENT ON COLUMN claims.encounter.paperwork_control_number IS '837P PWK - Identification Code';
COMMENT ON COLUMN claims.encounter.condition_codes IS '837P CRC - Condition Indicator Codes (comma-separated)';

-- Add new service line fields (HCP segment - Health Care Pricing)
ALTER TABLE claims.service_line
ADD COLUMN IF NOT EXISTS allowed_amount NUMERIC(10,2),
ADD COLUMN IF NOT EXISTS saving_amount NUMERIC(10,2);

COMMENT ON COLUMN claims.service_line.allowed_amount IS '837P HCP - Allowed Amount from adjudication';
COMMENT ON COLUMN claims.service_line.saving_amount IS '837P HCP - Saving Amount from adjudication';

-- Add indexes for commonly queried fields
CREATE INDEX IF NOT EXISTS idx_encounter_claim_number ON claims.encounter(claim_number) WHERE claim_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_encounter_ambulance ON claims.encounter(ambulance_transport_reason_code) WHERE ambulance_transport_reason_code IS NOT NULL;

